import Foundation
import XCTest
@testable import HealthOpsCore

/// Decodes the fixtures generated by the Python server tests from the real response models.
/// If the server contract changes, tests/test_assistant_fixtures.py regenerates the files and
/// this suite shows what the phone would make of them.
final class AssistantContractsTests: XCTestCase {
    func load(_ name: String) throws -> AskResponse {
        let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures/assistant")
        let data = try Data(contentsOf: XCTUnwrap(url, "missing fixture \(name)"))
        return try JSONDecoder().decode(AskResponse.self, from: data)
    }

    func testVerifiedAnswerShowsValuesAndTheVerifiedBadge() throws {
        let response = try load("answered_verified")
        XCTAssertEqual(response.status, .answered)
        XCTAssertEqual(response.explanationStatus, .verified)
        let presentation = AnswerPresentation(response)
        XCTAssertEqual(presentation.explanationBadge, .verified)
        XCTAssertTrue(presentation.showsCards)
        let rows = response.cards[0].rows
        XCTAssertEqual(rows.map(\.quality), [.value, .value, .none])
        XCTAssertEqual(rows[2].display, "no data")
        XCTAssertTrue(response.claims.allSatisfy(\.valid))
    }

    func testDegradedExplanationKeepsCardsAndNeverShowsVerified() throws {
        let response = try load("answered_unverified")
        XCTAssertEqual(response.status, .answered)
        XCTAssertEqual(AnswerPresentation(response).explanationBadge, .unverified)
        XCTAssertFalse(response.cards.isEmpty)
        XCTAssertFalse(response.claims.allSatisfy(\.valid))
    }

    func testUnusableRecordsAreNotNoData() throws {
        let response = try load("unusable_records")
        let rows = response.cards[0].rows
        XCTAssertEqual(rows.map(\.quality), [.unusable, .none, .value])
        XCTAssertEqual(rows[0].display, "no reliable value")
        XCTAssertEqual(rows[0].records, 2)
        XCTAssertEqual(rows[1].display, "no data")
        XCTAssertEqual(AnswerPresentation(response).explanationBadge, .verified)
        XCTAssertTrue(response.answer.contains("records exist"))
    }

    func testNoDataIsAnExplicitState() throws {
        let response = try load("insufficient_data")
        XCTAssertEqual(response.status, .insufficientData)
        // The server reports whatever the explanation step did; the phone must only never
        // show the verified badge for a window without usable data.
        XCTAssertNotEqual(AnswerPresentation(response).explanationBadge, .verified)
        XCTAssertEqual(AnswerPresentation(response).dataStatusLabel, "no usable data in that window")
    }

    func testRefusalIsFixedTextWithoutModelDetail() throws {
        let response = try load("refused")
        XCTAssertEqual(response.status, .refused)
        XCTAssertFalse(response.answer.contains("999"))  // the model detail stays in the debug field
        XCTAssertEqual(AnswerPresentation(response).explanationBadge, .notApplicable)
        XCTAssertFalse(AnswerPresentation(response).showsCards)
    }

    func testClarificationAndToolErrorDecode() throws {
        XCTAssertEqual(try load("needs_clarification").status, .needsClarification)
        let error = try load("tool_error")
        XCTAssertEqual(error.status, .toolError)
        XCTAssertEqual(AnswerPresentation(error).dataStatusLabel, "data query failed")
    }

    func testUnknownStatusesDecodeAsUnknownAndNeverEarnTheBadge() throws {
        let response = try load("unknown_status")
        XCTAssertEqual(response.status, .unknown)
        XCTAssertEqual(response.explanationStatus, .verified)
        XCTAssertEqual(AnswerPresentation(response).explanationBadge, .unverified)
        XCTAssertEqual(response.cards[0].rows[0].quality, .unknown)  // unknown quality text
    }

    func testReferenceAnswerDecodesAsAReferenceCard() throws {
        let response = try load("answered_reference")
        XCTAssertEqual(response.status, .answered)
        XCTAssertEqual(AnswerPresentation(response).explanationBadge, .verified)
        let card = try XCTUnwrap(response.cards.first)
        XCTAssertEqual(card.kind, .reference)
        XCTAssertEqual(card.publisher, "HealthOps project")
        XCTAssertTrue(card.text?.contains("SDNN") == true)
        XCTAssertTrue(card.sourceURL?.hasPrefix("https://") == true)
        XCTAssertTrue(response.answer.contains("not an assessment of your own values"))
    }

    func testUnparseableFindingDecodesWithNilClaim() throws {
        let response = try load("answered_unverified")
        XCTAssertTrue(response.claims.contains { $0.claim == nil && !$0.valid })
    }

    func testAskRequestEncodesOnlyTheContractFields() throws {
        let data = try ContractEncoding.encoder().encode(
            AskRequest(question: "q", timezone: "UTC", provider: nil))
        let object = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(Set(object.keys), ["question", "timezone"])  // nil provider is omitted, no `today`
    }
}
